#!/usr/bin/env node
// Bundles the public surface the documentation runs — the common facade's maths, diagnostic,
// quality and format tables, and the internal browser depth convention — into one browser
// module, so every demo of the portal executes the engine itself rather than a copy of it.
//
//   node scripts/docs-demo-bundle.mjs            writes docs/js/engine.js
//   node scripts/docs-demo-bundle.mjs --check    fails when the committed file is stale
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { build } from 'esbuild';

const ROOT = resolve(import.meta.dirname, '..');
const BUNDLE_PATH = 'docs/js/engine.js';
const BANNER = `// Generated by scripts/docs-demo-bundle.mjs from packages/ — do not edit.`;
const ENTRY = [
  // The whole public maths: every demo calls the function its page documents, by its own name.
  `export * from './common/math.ts';`,
  // The tables the enum pages show, read from the engine rather than copied into the page.
  `export { DIAGNOSTICS } from './common/diagnostics.ts';`,
  `export { LOD_QUALITY, adaptivePixelError, lodQuality } from './common/contracts.ts';`,
  `export { COLUMN_KIND } from './common/streaming.ts';`,
  // The portal explains this internal convention but does not present it as an application import.
  `export { DEPTH_CLEAR, DEPTH_COMPARE_OR_EQUAL, DEPTH_NEAR } from '../sdk-browser/depthConvention.ts';`,
].join('\n');

/** The bundle text: browser ESM, readable, a header naming its source. */
export async function bundleDemoMath() {
  const result = await build({
    stdin: { contents: ENTRY, resolveDir: resolve(ROOT, 'packages/sdk'), loader: 'ts' },
    bundle: true,
    format: 'esm',
    platform: 'browser',
    target: 'es2022',
    // Minified: this file is tracked, and the 200-line rule applies to it like any other
    // source. What proves it really is the engine is `check:docs-demo`, not reading it.
    minify: true,
    write: false,
    banner: { js: BANNER },
    logLevel: 'silent',
  });
  return result.outputFiles[0].text;
}

if (import.meta.filename === process.argv[1]) {
  const text = await bundleDemoMath();
  const target = resolve(ROOT, BUNDLE_PATH);
  if (process.argv.includes('--check')) {
    if (!existsSync(target) || readFileSync(target, 'utf8') !== text) {
      console.error(`${BUNDLE_PATH} is stale: run node scripts/docs-demo-bundle.mjs`);
      process.exit(1);
    }
  } else {
    writeFileSync(target, text);
    console.log(`${BUNDLE_PATH}: ${text.length} bytes`);
  }
}
